SELECT 'gongkao', '六面体', 'kp-xc-tutui-spatial-cube', CAST($${"type":"doc","content":[{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"六面体"}]},{"type":"highlightBlock","attrs":{"backgroundColor":"#fffbeb","borderColor":"#f59e0b","icon":"💡"},"content":[{"type":"paragraph","content":[{"type":"text","text":"核心结论：","marks":[{"type":"bold"}]},{"type":"text","text":"六面体是立体类最高频考点，核心方法：相对面排除法、公共边法、时针法。展开图中相对面永远不能同时被看到。"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"一、题型识别"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"折纸盒：展开图 → 立体图"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"拆纸盒：立体图 → 展开图"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"二、核心方法"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"相对面排除法：展开图中相隔一个面或 Z 字形两端的面是相对面，立体图中相对面只能出现一个"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"公共边法：相邻两个面的公共边两侧图案的相对位置在展开图和立体图中必须一致"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"时针法：相邻三个面在展开图和立体图中的时针方向必须一致"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"三、解题步骤"}]},{"type":"textDiagram","attrs":{"language":"mermaid"},"content":[{"type":"text","text":"flowchart TD\n    A[展开图/立体图] --> B[找相对面]\n    B --> C[排除相对面同时出现的选项]\n    C --> D[用公共边法验证剩余选项]\n    D --> E[用时针法最终确认]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"四、易错点"}]},{"type":"highlightBlock","attrs":{"backgroundColor":"#fef2f2","borderColor":"#ef4444","icon":"⚠️"},"content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"相对面判断：相隔一个面 OR Z 字形两端且只相隔一列"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"向内折，折完要能看到图案"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"四个面相连、上下各一个面，一定能折成六面体"}]}]}]}]},{"type":"highlightBlock","attrs":{"backgroundColor":"#eff6ff","borderColor":"#3b82f6","icon":"📊"},"content":[{"type":"paragraph","content":[{"type":"text","text":"刷题建议：","marks":[{"type":"bold"}]},{"type":"text","text":"六面体在图形推理中占比约 10%，是立体类最高频考点。必须熟练掌握相对面排除法和公共边法，建议每天练习 3-5 道。"}]}]}]}$$ AS jsonb), NULL, '图形推理立体类-六面体的核心考点：折纸盒、拆纸盒、相对面排除法、公共边法。', category_node.id, CAST('["图形推理", "立体空间", "六面体", "折纸盒", "相对面"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xc_tuTui_spatial_cube", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, extra = EXCLUDED.extra, updated_time = NOW();
